/** Chance of each offer slot rolling each tier; then a random item of that tier. */
export const TIER_CHANCE = { basic: 0.68, epic: 0.28, legendary: 0.04 };

export function rollOffers(count = 3): Item[] {
  const out: Item[] = [];
  while (out.length < count) {
    const r = Math.random();
    const tier = r < TIER_CHANCE.legendary ? 'legendary' : r < TIER_CHANCE.legendary + TIER_CHANCE.epic ? 'epic' : 'basic';
    const pool = Object.values(ITEMS).filter((i) => i.tier === tier && !out.includes(i));
    out.push(pool[Math.floor(Math.random() * pool.length)]);
  }
  return out;
}

/** Items whose full recipe is in the inventory (multiset match). There is no gold, so components alone are enough. */
export function combinable(inventory: string[]): Item[] {
  return Object.values(ITEMS).filter((it) => {
    if (!it.from.length) return false;
    const left = [...inventory];
    return it.from.every((c) => {
      const i = left.indexOf(c);
      if (i < 0) return false;
      left.splice(i, 1);
      return true;
    });
  });
}

/** Best recipe the offered item finishes together with the inventory (legendary first, then the biggest recipe). */
export function completedBy(inventory: string[], id: string): Item | undefined {
  const rank = { legendary: 2, epic: 1, basic: 0 };
  return combinable([...inventory, id])
    .filter((it) => it.from.includes(id))
    .sort((a, b) => rank[b.tier] - rank[a.tier] || b.from.length - a.from.length)[0];
}

export function combine(inventory: string[], item: Item): string[] {
  const left = [...inventory];
  for (const c of item.from) left.splice(left.indexOf(c), 1);
  return [...left, item.id];
}

/** Legendaries this item eventually builds into. */
export function buildsInto(id: string): Item[] {
  const out = new Set<Item>();
  const walk = (i: string) => {
    for (const p of ITEMS[i].into) {
      if (ITEMS[p].tier === 'legendary') out.add(ITEMS[p]);
      else walk(p);
    }
  };
  walk(id);
  return [...out];
}

export function sumStats(inventory: string[]): Required<ItemStats> {
  const s: Required<ItemStats> = {
    ad: 0, as: 0, hp: 0, mana: 0, crit: 0, armor: 0, msPct: 0, lifesteal: 0, omnivamp: 0, ah: 0, armorPen: 0, critDamage: 0,
  };
  for (const id of inventory) {
    for (const [k, v] of Object.entries(ITEMS[id].stats)) {
      // armor penetration doesn't stack additively in LoL; keep the best source
      if (k === 'armorPen') s.armorPen = Math.max(s.armorPen, v);
      else s[k as keyof ItemStats] += v;
    }
  }
  return s;
}

const STAT_LABEL: Record<keyof ItemStats, (v: number) => string> = {
  ad: (v) => `+${v} DdA`, as: (v) => `+${Math.round(v * 100)}% Vel. Ataque`, hp: (v) => `+${v} Vida`, mana: (v) => `+${v} Mana`,
  crit: (v) => `+${Math.round(v * 100)}% Crítico`, armor: (v) => `+${v} Armadura`, msPct: (v) => `+${Math.round(v * 100)}% Vel. Movimento`,
  lifesteal: (v) => `+${Math.round(v * 100)}% Roubo de Vida`, omnivamp: (v) => `+${Math.round(v * 100)}% Vampirismo`,
  ah: (v) => `+${v} Acel. Habilidade`, armorPen: (v) => `+${Math.round(v * 100)}% Pen. Armadura`,
  critDamage: (v) => `+${Math.round(v * 100)}% Dano Crítico`,
};
export const describeStats = (s: ItemStats) =>
  Object.entries(s).map(([k, v]) => STAT_LABEL[k as keyof ItemStats](v)).join(' · ');
